mapper.select:
SELECT b.pay_time AS payTime, b.order_no AS orderNo, r.room_number AS roomNumber, rt.name AS roomTypeName, b.guest_name AS guestName, DATEDIFF(b.check_out_date, b.check_in_date) AS stayDays, b.total_price AS amount, b.check_in_date AS checkInDate FROM booking b LEFT JOIN room r ON b.room_id = r.id LEFT JOIN room_type rt ON r.room_type_id = rt.id
AND b.pay_time >= #{startDate}
AND b.pay_time <= #{endDate}
AND r.room_type_id = #{roomTypeId}
AND b.status = #{status}
ORDER BY b.pay_time DESC
